// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 t, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        t = bound(t, 1, type(uint64).max);

        vm.deal(actor, 20 ether);

        // First call at timestamp t: succeeds in both versions (t > 0 = pastBlockTime).
        vm.warp(t);
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1, "first call should succeed");

        // Second call at the SAME timestamp t: pastBlockTime is now t, so
        // block.timestamp must be strictly greater -> must revert in reference.
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: 10 ether}("");

        // General rule: a same-timestamp repeat call always reverts.
        assertTrue(!ok2, "same-timestamp second fallback call must revert");
    }
}
